<?php
$base='http://localhost:8000'; $cookie='scripts_debug_cookie.txt'; @unlink($cookie);
function req($url,$cookie=null,$post=null,$headers=[]) { $ch=curl_init($url); curl_setopt($ch,CURLOPT_RETURNTRANSFER,true); curl_setopt($ch,CURLOPT_HEADER,true); if($cookie){curl_setopt($ch,CURLOPT_COOKIEJAR,$cookie); curl_setopt($ch,CURLOPT_COOKIEFILE,$cookie);} if($post!==null){curl_setopt($ch,CURLOPT_POST,true); curl_setopt($ch,CURLOPT_POSTFIELDS,$post);} if($headers) curl_setopt($ch,CURLOPT_HTTPHEADER,$headers); curl_setopt($ch,CURLOPT_FOLLOWLOCATION,false); curl_setopt($ch,CURLOPT_TIMEOUT,20); $res=curl_exec($ch); if($res===false){$err=curl_error($ch); curl_close($ch); return ['ok'=>false,'error'=>$err];} $c=curl_getinfo($ch,CURLINFO_HTTP_CODE); $hlen=curl_getinfo($ch,CURLINFO_HEADER_SIZE); $header=substr($res,0,$hlen); $body=substr($res,$hlen); curl_close($ch); return ['ok'=>true,'status'=>$c,'header'=>$header,'body'=>$body]; }
$r=req($base.'/sanctum/csrf-cookie',$cookie); echo "csrf status={$r['status']}\n"; $lines=file($cookie,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES); foreach($lines as $ln){ if($ln[0]=='#') continue; $p=preg_split('/\s+/',$ln); if(count($p)>=7 && $p[5]=='XSRF-TOKEN'){ $xs=urlencode($p[6]); echo "found xsrf={$p[6]}\n"; break;} }
$post=http_build_query(['email'=>'admin@school.com','password'=>'password']); $r2=req($base.'/login',$cookie,$post,['Content-Type: application/x-www-form-urlencoded','X-XSRF-TOKEN: '.urldecode($p[6])]); echo "login status={$r2['status']}\n"; echo "login header:\n".substr($r2['header'],0,400)."\n";
$post2=http_build_query(['name'=>'DbgClass'.time(),'grade_level'=>'10','sections[]'=>'A']); $r3=req($base.'/classes',$cookie,$post2,['Content-Type: application/x-www-form-urlencoded','X-XSRF-TOKEN: '.urldecode($p[6])]);
echo "create status={$r3['status']}\n"; echo "create header:\n".substr($r3['header'],0,800)."\n"; echo "create body snippet:\n".substr($r3['body'],0,1200)."\n"; 
file_put_contents('scripts/debug_cookie_dump.txt', implode("\n", $lines));
